	["I attack everything nearby"] = { de = "Ich greife alles in der N\228he an", fr = "J'attaque tout ce qui est proche", pt = "Ataco tudo o que estiver perto", ro = "Atac tot ce e prin apropiere", tr = "Yak\253ndaki her \254eye sald\253r\253r\253m" },
	["I never attack first"] = { de = "Ich greife nie zuerst an", fr = "Je n'attaque jamais en premier", pt = "Nunca ataco primeiro", ro = "Nu atac niciodata primul", tr = "Asla ilk sald\253rmam" },
	["I don't fight, I only defend"] = { de = "Ich k\228mpfe nicht, ich verteidige nur", fr = "Je ne combats pas, je me d\233fends seulement", pt = "N\227o luto, s\243 me defendo", ro = "Nu lupt, doar ma apar", tr = "Sava\254mam, sadece savunurum" },
	["No change"] = { de = "Keine \196nderung", fr = "Aucun changement", pt = "Sem altera\231\227o", ro = "Nicio schimbare", tr = "De\240i\254iklik yok" },
	["Sure? Your companion leaves, and its character"] = { de = "Sicher? Dein Gef\228hrte geht, und sein Charakter", fr = "S\251r ? Votre compagnon s'en va et son personnage", pt = "Tens a certeza? O teu companheiro parte e a personagem", ro = "Sigur? Tovarasul pleaca, iar personajul lui", tr = "Emin misin? Yolda\254\253n ayr\253l\253r ve karakteri" },
	["goes back to the world as an ordinary bot. You"] = { de = "kehrt als gew\246hnlicher Bot in die Welt zur\252ck. Du", fr = "retourne dans le monde comme un bot ordinaire. Vous", pt = "volta ao mundo como um bot comum. Podes", ro = "revine in lume ca un bot obisnuit. Puteti", tr = "s\253radan bir bot olarak d\252nyaya geri d\246ner." },
	["can choose a new one right away."] = { de = "kannst sofort einen neuen w\228hlen.", fr = "pouvez en choisir un nouveau tout de suite.", pt = "escolher um novo de imediato.", ro = "alege imediat unul nou.", tr = "Hemen yenisini se\231ebilirsin." },
	["Yes, leave"] = { de = "Ja, gehen", fr = "Oui, partir", pt = "Sim, partir", ro = "Da, pleaca", tr = "Evet, ayr\253l" },
